  /* v29.0.3: журнал усечения возвращён (v29.0.2 снял — H13 требовал честности) */
  if (rawAll.length > 400) journal.debug('core', 'dedupeNested: усечение кандидатов ' + rawAll.length + ' → 400 (жёсткий кап — хвост списка теряется, это НЕ ошибка выборки)');
  const arr = rawAll.slice(0, 400);
  if (arr.length < 2) return arr;
  const set = new Set(arr);
  const nearAnc = el => { let p = gp(el); while (p) { if (set.has(p)) return p; p = gp(p); } return null; };
  const heldBy = new Map();
  for (const el of arr) { const a = nearAnc(el); if (a) heldBy.set(a, (heldBy.get(a) || 0) + 1); }
