  if (cand.animNoise) m.addEvidence('class', 0.9, 'noise', 'typing/indicator/spinner/skeleton');
  if (cand.uiZone) m.addEvidence('ui-zone', 0.8, 'noise', 'кнопка/навигация/форма');
  if (!cand.attr && m.text.trim().length < 2) m.addEvidence('text', 0.2, 'noise', 'пусто без атрибутной улики');
