    if (v === undefined) { stat.missing++; rows.push({ i: b.index, base: b.role, shadow: null, d: 'missing' }); continue; }
    if (v === 'unknown') { stat.shadowUnknown++; rows.push({ i: b.index, base: b.role, shadow: 'unknown', d: 'shadow-unknown' }); continue; }
    if (b.role === 'unknown') { stat.baseUnknownShadowKnown++; rows.push({ i: b.index, base: 'unknown', shadow: v, d: 'base-unknown' }); continue; }
