  const L = ['---'];
  L.push('title: "' + yamlEsc(cd.title || 'Экспорт чата') + '"');
  L.push('source: "' + yamlEsc(cd.url || '') + '"');
  L.push('platform: "' + yamlEsc(cd.platform || 'unknown') + '"');
  L.push('captured_at: "' + yamlEsc(cd.capturedAt) + '"');
  L.push('capture_mode: "' + yamlEsc(cd.captureMode) + '"');
  L.push('message_count: ' + (ig.messageCount || 0));
