    if (!att || !att.payload || !att.sig) return { ok: false, reason: 'нет payload/sig' };
    if (typeof crypto === 'undefined' || !crypto || !crypto.subtle) return { ok: false, reason: 'crypto.subtle недоступен' };
    const k = await ensureAttestKey(false);
    if (att.keyId !== k.keyId) return { ok: false, reason: 'keyId не совпадает с локальным ключом (передайте публичный JWK верификатору)' };
