function kinematicHypothesis(baseItems) {
  /* ГИПОТЕЗА ролей по X-сдвигу bbox — строго В ТЕНИ (решение владельца «Тень-гипотеза»):
     hypothesis:true, method:'kinematic-geometry', confidence 0.55 (ниже structural-order
     0.60 лестницы). НИКОГДА не попадает в экспорт — только протокол разногласия. */
  const out = [];
  let prevX = null;
  for (const b of (baseItems || [])) {
    let x = null, w = null;
    try { if (b.el && b.el.getBoundingClientRect) { const r = b.el.getBoundingClientRect(); x = Math.round(r.left); w = Math.round(r.width); } } catch (eK) {}
    if (x == null) { out.push({ index: b.index, hypothesis: true, method: 'kinematic-geometry', confidence: 0.55, guess: 'unknown', reason: 'нет геометрии' }); continue; }
    let guess = 'unknown';
    if (prevX != null && x > prevX + 15) guess = 'user';
    else if (prevX != null && x < prevX - 15) guess = 'assistant';
    else if (prevX == null) guess = x > 200 ? 'user' : 'assistant';
    out.push({ index: b.index, hypothesis: true, method: 'kinematic-geometry', confidence: 0.55, guess, reason: 'x=' + x + 'px, w=' + w + 'px' });
    prevX = x;
  }
  return out;
}
