  let hypo = [];
  try { hypo = kinematicHypothesis(baseItems); } catch (eH) { journal.debug('shadow', 'kinematic-fail', String(eH && eH.message || eH)); }
  shadowState.lastDiff = { at: nowMs(), ver: shadowState.ver, n: results.length, stat: diff.stat, rows: diff.rows.slice(0, 50), hypothesis: hypo }; /* v32: гипотеза кинематики — ТОЛЬКО тень, не экспорт */
  const s = diff.stat;
  const msg = 'diff: agree ' + s.agree + ', disagree ' + s.disagree + ', base-unknown→known ' + s.baseUnknownShadowKnown + ', shadow-unknown ' + s.shadowUnknown + ', missing ' + s.missing + ' (из ' + results.length + ')';
  if (s.disagree > 0) journal.warn('shadow', msg, JSON.stringify(diff.rows.filter(r => r.d === 'disagree').slice(0, 10)));
