        const val = typeof h.value === 'object' ? JSON.stringify(h.value) : h.value;
        const cls = h.verdict === 'fail' ? 'v-fail' : h.verdict === 'warn' ? 'v-warn' : 'v-ok';
        const tag = h.verdict === 'fail' ? '[FAIL]' : h.verdict === 'warn' ? '[WARN]' : '[OK]';
        return `<tr class="${cls}"><td><strong>${esc(h.id)}</strong></td><td>${esc(String(val))}</td><td>${esc(h.unit)}</td><td>${esc(h.threshold)}</td><td><span class="verdict">${esc(tag)}</span></td><td>${esc(h.ref)}</td></tr>`;
