    cands.push({ top: o.top + o.height + 16, left: x }); /* под препятствием */
    cands.push({ top: y, left: o.left - w - 16 });       /* левее препятствия */
    cands.push({ top: y, left: o.left + o.width + 16 }); /* правее препятствия */
