    if (e.button !== 0) return;
    if (e.target && e.target.closest && e.target.closest('button, input, select, textarea, a')) return; /* за элементы управления не таскаем */
    const r = box.getBoundingClientRect();
    drag = true; dragMoved = false; dx = e.clientX - r.left; dy = e.clientY - r.top; /* v34.0.0 */
    e.preventDefault();
